export interface SegmentedControlProps extends RadioGroupPrimitive.Props<string> {
  appearance?: SegmentedControlAppearance
  color?: SegmentedControlColor
  density?: SegmentedControlDensity
  fillImageHref?: string
  fullWidth?: boolean
  orientation?: SegmentedControlOrientation
}

interface SegmentedControlContextValue {
  appearance: SegmentedControlAppearance
  color: SegmentedControlColor
  fillImageHref: string
}

const SegmentedControlContext = React.createContext<SegmentedControlContextValue | null>(null)

function SegmentedControl({
  ref,
  appearance = 'buttons',
  className,
  color = 'yellow',
  density = 'default',
  fillImageHref = '/_images/backgrounds/camo-green.png',
  fullWidth = false,
  orientation = 'horizontal',
  children,
  ...props
}: SegmentedControlProps & { ref?: React.Ref<HTMLDivElement> }) {
  const contextValue = React.useMemo<SegmentedControlContextValue>(
    () => ({ appearance, color, fillImageHref }),
    [appearance, color, fillImageHref]
  )

  return (
    <SegmentedControlContext.Provider value={contextValue}>
      <RadioGroupPrimitive
        ref={ref}
        data-slot="segmented-control"
        data-appearance={appearance}
        data-color={color}
        data-density={density}
        data-full-width={fullWidth ? 'true' : undefined}
        data-orientation={orientation}
        aria-orientation={orientation}
        className={cn(
          styles.root,
          appearance === 'buttons' ? buttonGroupStyles.root : undefined,
          className
        )}
        {...props}
      >
        {appearance === 'track' ? <SegmentedTrackLayer fillImageHref={fillImageHref} /> : null}
        {children}
      </RadioGroupPrimitive>
    </SegmentedControlContext.Provider>
  )
}

export interface SegmentedControlItemProps extends RadioPrimitive.Root.Props<string> {
  buttonProps?: Omit<ButtonGroupItemProps, 'children' | 'ref' | 'value'>
  /** Which slice of the official switch track this item paints (track appearance only). */
  trackPosition?: SegmentedTrackPosition
}

function getCheckedButtonVariant(color: SegmentedControlColor): ButtonGroupItemProps['variant'] {
  return color
}

function getCheckedButtonTheme(color: SegmentedControlColor): ButtonGroupItemProps['theme'] {
  if (color === 'yellow') {
    return 'dark-yellow'
  }

  if (color === 'blue') {
    return 'light-blue'
  }

  if (color === 'green') {
    return 'light-green'
  }

  if (color === 'purple') {
    return 'dark-purple'
  }

  return 'dark-purpleOrange'
}

function getOutlineButtonTheme(color: SegmentedControlColor): ButtonGroupItemProps['theme'] {
  if (color === 'blue') {
    return 'light-blue'
  }

  if (color === 'green') {
    return 'light-green'
  }

  if (color === 'purple') {
    return 'dark-purple'
  }

  if (color === 'orange') {
    return 'dark-purpleOrange'
  }

  return 'yellow'
}

/**
 * The track background. Renders every official switch half in one shared
 * 0..300 viewBox so the seams are continuous. Active/inactive is driven
 * purely by which radio item carries [data-checked] (Base UI sets it),
 * via :has() in the stylesheet — no state plumbing needed.
 */
function SegmentedTrackLayer({ fillImageHref }: { fillImageHref: string }) {
  const id = React.useId().replace(/:/g, '')
  const leftClipId = `segmented-track-left-${id}`
  const middleClipId = `segmented-track-middle-${id}`
  const rightClipId = `segmented-track-right-${id}`
  const fillPatternId = `segmented-track-fill-${id}`
  const inactiveFilterId = `segmented-track-inactive-${id}`

  return (
    <svg
      className={styles.trackLayer}
      viewBox={SEGMENTED_TRACK_VIEW_BOX}
      preserveAspectRatio="none"
      focusable="false"
      aria-hidden="true"
    >
      <defs>
        <clipPath id={leftClipId}>
          <path d={SEGMENTED_TRACK_LEFT_PATH} />
        </clipPath>
        <clipPath id={middleClipId}>
          <path d={SEGMENTED_TRACK_MIDDLE_PATH} />
        </clipPath>
        <clipPath id={rightClipId}>
          <path d={SEGMENTED_TRACK_RIGHT_PATH} />
        </clipPath>
        <SwitchTrackPatternDefs
          fillImageHref={fillImageHref}
          fillPatternId={fillPatternId}
          inactiveFilterId={inactiveFilterId}
          patternTileSize={TRACK_PATTERN_TILE_SIZE}
          patternRepeatX={TRACK_PATTERN_REPEAT_X}
          patternRepeatY={TRACK_PATTERN_REPEAT_Y}
        />
      </defs>
      <g className={styles.trackShapeLeft} clipPath={`url(#${leftClipId})`}>
        <rect
          className={styles.trackSegmentInactive}
          x="-4"
          y="-2"
          width="308"
          height="36"
          fill={`url(#${fillPatternId})`}
          filter={`url(#${inactiveFilterId})`}
        />
        <rect
          className={styles.trackSegmentActive}
          x="-4"
          y="-2"
          width="308"
          height="36"
          fill={`url(#${fillPatternId})`}
        />
      </g>
      <g className={styles.trackShapeMiddle} clipPath={`url(#${middleClipId})`}>
        <rect
          className={styles.trackSegmentInactive}
          x="-4"
          y="-2"
          width="308"
          height="36"
          fill={`url(#${fillPatternId})`}
          filter={`url(#${inactiveFilterId})`}
        />
        <rect
          className={styles.trackSegmentActive}
          x="-4"
          y="-2"
          width="308"
          height="36"
          fill={`url(#${fillPatternId})`}
        />
      </g>
      <g className={styles.trackShapeRight} clipPath={`url(#${rightClipId})`}>
        <rect
          className={styles.trackSegmentInactive}
          x="-4"
          y="-2"
          width="308"
          height="36"
          fill={`url(#${fillPatternId})`}
          filter={`url(#${inactiveFilterId})`}
        />
        <rect
          className={styles.trackSegmentActive}
          x="-4"
          y="-2"
          width="308"
          height="36"
          fill={`url(#${fillPatternId})`}
        />
      </g>
    </svg>
  )
}

function SegmentedControlItem({
  ref,
  buttonProps,
  className,
  trackPosition,
  children,
  ...props
}: SegmentedControlItemProps & { ref?: React.Ref<HTMLElement> }) {
  const context = React.useContext(SegmentedControlContext)
  const appearance = context?.appearance ?? 'buttons'
  const color = context?.color ?? 'yellow'

  if (appearance === 'buttons') {
    return (
      <RadioPrimitive.Root
        ref={ref}
        data-slot="segmented-control-item"
        className={cn(styles.item, buttonGroupStyles.item, styles.buttonItem, className)}
        render={(renderProps, state) => {
          const { color: omittedDomColor, ...buttonRenderProps } = renderProps
          void omittedDomColor

          return (
            <ButtonGroupItem
              {...buttonProps}
              {...buttonRenderProps}
              hasChevron={buttonProps?.hasChevron ?? false}
              size={buttonProps?.size ?? 'sm'}
              theme={
                buttonProps?.theme ??
                (state.checked ? getCheckedButtonTheme(color) : getOutlineButtonTheme(color))
              }
              variant={
                buttonProps?.variant ?? (state.checked ? getCheckedButtonVariant(color) : 'outline')
              }
              className={cn(renderProps.className, buttonProps?.className)}
            >
              {children}
            </ButtonGroupItem>
          )
        }}
        {...props}
      />
    )
  }

  // Track appearance: item is a transparent hit/label surface over the
  // shared track layer. Which slice it represents is tagged for :has() CSS.
  const position = trackPosition ?? 'middle'

  return (
    <RadioPrimitive.Root
      ref={ref}
      data-slot="segmented-control-item"
      data-track-position={position}
      className={cn(styles.item, styles.trackItem, className)}
      {...props}
    >
      <span className={styles.label}>{children}</span>
    </RadioPrimitive.Root>
  )
}

export { SegmentedControl, SegmentedControlItem }
